import{_ as i,c as n,o as a,ag as r}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse('{"title":"Häufig gestellte Fragen","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/faq.md","filePath":"de/guide/faq.md","lastUpdated":1794112334000}'),t={name:"de/guide/faq.md"};function s(l,e,h,c,u,o){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="haufig-gestellte-fragen" tabindex="-1">Häufig gestellte Fragen <a class="header-anchor" href="#haufig-gestellte-fragen" aria-label="Permalink to &quot;Häufig gestellte Fragen&quot;">​</a></h1><h2 id="allgemeine-fragen" tabindex="-1">Allgemeine Fragen <a class="header-anchor" href="#allgemeine-fragen" aria-label="Permalink to &quot;Allgemeine Fragen&quot;">​</a></h2><h3 id="was-ist-nicasa" tabindex="-1">Was ist Nicasa? <a class="header-anchor" href="#was-ist-nicasa" aria-label="Permalink to &quot;Was ist Nicasa?&quot;">​</a></h3><p>Nicasa ist ein moderner Desktop-Bildbetrachter und ein Screenshot-Tool, das exklusiv für macOS entwickelt wurde. Es bietet schnelle, intuitive Navigation durch deine Bildsammlungen mit einer klaren, reaktionsschnellen Oberfläche und leistungsstarken KI-Bearbeitungsfunktionen.</p><h3 id="ist-nicasa-kostenlos" tabindex="-1">Ist Nicasa kostenlos? <a class="header-anchor" href="#ist-nicasa-kostenlos" aria-label="Permalink to &quot;Ist Nicasa kostenlos?&quot;">​</a></h3><p>Die Chrome-Erweiterung ist völlig kostenlos. Die macOS-App erfordert einen einmaligen Kauf von 4,99 $ für den vollen Funktionsumfang.</p><h3 id="welche-betriebssysteme-werden-unterstutzt" tabindex="-1">Welche Betriebssysteme werden unterstützt? <a class="header-anchor" href="#welche-betriebssysteme-werden-unterstutzt" aria-label="Permalink to &quot;Welche Betriebssysteme werden unterstützt?&quot;">​</a></h3><p>Nicasa ist derzeit ausschließlich für macOS 10.13 oder neuer verfügbar. Windows- und Linux-Versionen gibt es derzeit nicht.</p><h3 id="wie-aktualisiere-ich-nicasa" tabindex="-1">Wie aktualisiere ich Nicasa? <a class="header-anchor" href="#wie-aktualisiere-ich-nicasa" aria-label="Permalink to &quot;Wie aktualisiere ich Nicasa?&quot;">​</a></h3><p>Updates laufen über den Mac App Store. Du wirst benachrichtigt, wenn Updates verfügbar sind, und kannst direkt über die App-Store-App aktualisieren.</p><h2 id="fragen-zur-nutzung" tabindex="-1">Fragen zur Nutzung <a class="header-anchor" href="#fragen-zur-nutzung" aria-label="Permalink to &quot;Fragen zur Nutzung&quot;">​</a></h2><h3 id="wie-erstelle-ich-screenshots-mit-nicasa" tabindex="-1">Wie erstelle ich Screenshots mit Nicasa? <a class="header-anchor" href="#wie-erstelle-ich-screenshots-mit-nicasa" aria-label="Permalink to &quot;Wie erstelle ich Screenshots mit Nicasa?&quot;">​</a></h3><ol><li>Starte Nicasa</li><li>Klicke auf die Screenshot-Schaltfläche in der Symbolleiste oder verwende <code>Cmd+S</code></li><li>Wähle den Bereich aus, den du erfassen möchtest</li><li>Der Screenshot öffnet sich in Nicasa zur sofortigen Bearbeitung</li></ol><h3 id="funktioniert-nicasa-mit-webbildern" tabindex="-1">Funktioniert Nicasa mit Webbildern? <a class="header-anchor" href="#funktioniert-nicasa-mit-webbildern" aria-label="Permalink to &quot;Funktioniert Nicasa mit Webbildern?&quot;">​</a></h3><p>Ja! Installiere die kostenlose Nicasa Chrome-Erweiterung, um:</p><ul><li>alle Bilder jeder Webseite an einem Ort zu sehen</li><li>Bilder sofort zu extrahieren und zu durchstöbern</li><li>Bilder direkt in Nicasa für eine bessere Ansicht zu öffnen</li></ul><h3 id="welche-ki-bearbeitungsfunktionen-gibt-es" tabindex="-1">Welche KI-Bearbeitungsfunktionen gibt es? <a class="header-anchor" href="#welche-ki-bearbeitungsfunktionen-gibt-es" aria-label="Permalink to &quot;Welche KI-Bearbeitungsfunktionen gibt es?&quot;">​</a></h3><p>Nicasa enthält leistungsstarke KI-Werkzeuge:</p><ul><li><strong>Automatische Verbesserung</strong>: Bildqualität automatisch steigern</li><li><strong>Intelligentes Zuschneiden</strong>: intelligente Zuschnittvorschläge</li><li><strong>Inpainting</strong>: unerwünschte Objekte intelligent entfernen</li><li><strong>Farbkorrektur</strong>: KI-gestützte Farbanpassungen</li><li><strong>Rauschreduzierung</strong>: Rauschen und Körnung entfernen</li></ul><h3 id="wie-funktioniert-der-transparente-overlay-modus" tabindex="-1">Wie funktioniert der transparente Overlay-Modus? <a class="header-anchor" href="#wie-funktioniert-der-transparente-overlay-modus" aria-label="Permalink to &quot;Wie funktioniert der transparente Overlay-Modus?&quot;">​</a></h3><p>Perfekt für Designer und Künstler:</p><ul><li>Bilder mit einstellbarer Transparenz über allen Fenstern anheften</li><li>Zum Nachzeichnen, für Referenzarbeit oder UI-Vergleiche nutzen</li><li>Behält die Position über alle Anwendungen hinweg bei</li></ul><h2 id="technische-fragen" tabindex="-1">Technische Fragen <a class="header-anchor" href="#technische-fragen" aria-label="Permalink to &quot;Technische Fragen&quot;">​</a></h2><h3 id="warum-muss-ich-die-berechtigung-zur-bildschirmaufnahme-erteilen" tabindex="-1">Warum muss ich die Berechtigung zur Bildschirmaufnahme erteilen? <a class="header-anchor" href="#warum-muss-ich-die-berechtigung-zur-bildschirmaufnahme-erteilen" aria-label="Permalink to &quot;Warum muss ich die Berechtigung zur Bildschirmaufnahme erteilen?&quot;">​</a></h3><p>Die Berechtigung zur Bildschirmaufnahme ist für die Screenshot-Funktion erforderlich. Sie erlaubt Nicasa, deinen Bildschirm zu erfassen, wenn du das Screenshot-Werkzeug verwendest.</p><h3 id="kann-ich-nicasa-offline-verwenden" tabindex="-1">Kann ich Nicasa offline verwenden? <a class="header-anchor" href="#kann-ich-nicasa-offline-verwenden" aria-label="Permalink to &quot;Kann ich Nicasa offline verwenden?&quot;">​</a></h3><p>Ja. Die macOS-App funktioniert bei lokalen Bilddateien vollständig offline. Das Extrahieren von Webbildern über die Chrome-Erweiterung erfordert eine Internetverbindung.</p><h3 id="welche-macos-versionen-werden-unterstutzt" tabindex="-1">Welche macOS-Versionen werden unterstützt? <a class="header-anchor" href="#welche-macos-versionen-werden-unterstutzt" aria-label="Permalink to &quot;Welche macOS-Versionen werden unterstützt?&quot;">​</a></h3><p>Nicasa unterstützt macOS 10.13 oder neuer. Es ist für Apple Silicon optimiert und läuft nativ auf Chips der M-Serie.</p><h3 id="welche-berechtigungen-braucht-die-chrome-erweiterung" tabindex="-1">Welche Berechtigungen braucht die Chrome-Erweiterung? <a class="header-anchor" href="#welche-berechtigungen-braucht-die-chrome-erweiterung" aria-label="Permalink to &quot;Welche Berechtigungen braucht die Chrome-Erweiterung?&quot;">​</a></h3><p>Die Erweiterung fordert Zugriff auf Seiteninhalte ausschließlich zum Extrahieren von Bild-URLs an. Der Browserverlauf wird weder gelesen noch gespeichert.</p><h3 id="werden-meine-daten-irgendwohin-hochgeladen" tabindex="-1">Werden meine Daten irgendwohin hochgeladen? <a class="header-anchor" href="#werden-meine-daten-irgendwohin-hochgeladen" aria-label="Permalink to &quot;Werden meine Daten irgendwohin hochgeladen?&quot;">​</a></h3><p>Nein. Die gesamte Verarbeitung erfolgt lokal auf deinem Gerät. Nicasa sammelt, überträgt oder speichert deine Bilder nicht.</p><h3 id="wie-sichere-ich-meine-einstellungen" tabindex="-1">Wie sichere ich meine Einstellungen? <a class="header-anchor" href="#wie-sichere-ich-meine-einstellungen" aria-label="Permalink to &quot;Wie sichere ich meine Einstellungen?&quot;">​</a></h3><p>Deine Einstellungen werden lokal gespeichert. Zum Sichern:</p><ol><li>Gehe zu Nicasa &gt; Einstellungen</li><li>Exportiere deine Einstellungen, falls verfügbar</li><li>Oder sichere den Ordner mit den App-Einstellungen manuell</li></ol><p>Die Einstellungen liegen im Datenordner der App. Kopiere diesen Ordner, um deine Einstellungen zu sichern.</p><h3 id="gibt-es-eine-portable-version" tabindex="-1">Gibt es eine portable Version? <a class="header-anchor" href="#gibt-es-eine-portable-version" aria-label="Permalink to &quot;Gibt es eine portable Version?&quot;">​</a></h3><p>Für Windows gibt es eine portable Version. Lade sie von unserer Webseite herunter.</p><h2 id="entwicklungsfragen" tabindex="-1">Entwicklungsfragen <a class="header-anchor" href="#entwicklungsfragen" aria-label="Permalink to &quot;Entwicklungsfragen&quot;">​</a></h2><h3 id="kann-ich-zu-nicasa-beitragen" tabindex="-1">Kann ich zu Nicasa beitragen? <a class="header-anchor" href="#kann-ich-zu-nicasa-beitragen" aria-label="Permalink to &quot;Kann ich zu Nicasa beitragen?&quot;">​</a></h3><p>Besuche unser <a href="https://github.com/nicasa-project/nicasa-support" target="_blank" rel="noreferrer">GitHub-Repository</a>, um Code beizutragen, Probleme zu melden oder Funktionen vorzuschlagen.</p><h3 id="wie-baue-ich-nicasa-aus-dem-quellcode" tabindex="-1">Wie baue ich Nicasa aus dem Quellcode? <a class="header-anchor" href="#wie-baue-ich-nicasa-aus-dem-quellcode" aria-label="Permalink to &quot;Wie baue ich Nicasa aus dem Quellcode?&quot;">​</a></h3><p>Siehe unsere Entwicklerdokumentation auf GitHub für Build-Anweisungen.</p><h3 id="welche-technologien-verwendet-nicasa" tabindex="-1">Welche Technologien verwendet Nicasa? <a class="header-anchor" href="#welche-technologien-verwendet-nicasa" aria-label="Permalink to &quot;Welche Technologien verwendet Nicasa?&quot;">​</a></h3><p>Nicasa ist mit modernen Webtechnologien gebaut, darunter Electron als Desktop-Hülle und Vue.js für die Oberfläche.</p><h2 id="datenschutzfragen" tabindex="-1">Datenschutzfragen <a class="header-anchor" href="#datenschutzfragen" aria-label="Permalink to &quot;Datenschutzfragen&quot;">​</a></h2><h3 id="sammelt-nicasa-daten" tabindex="-1">Sammelt Nicasa Daten? <a class="header-anchor" href="#sammelt-nicasa-daten" aria-label="Permalink to &quot;Sammelt Nicasa Daten?&quot;">​</a></h3><p>Nein, Nicasa sammelt und überträgt keine personenbezogenen Daten. Die gesamte Bildverarbeitung erfolgt lokal auf deinem Gerät.</p><h3 id="sind-meine-bilder-sicher" tabindex="-1">Sind meine Bilder sicher? <a class="header-anchor" href="#sind-meine-bilder-sicher" aria-label="Permalink to &quot;Sind meine Bilder sicher?&quot;">​</a></h3><p>Ja. Nicasa greift nur auf Bilder zu, die du ausdrücklich öffnest. Es lädt deine Dateien nicht hoch und teilt sie nicht.</p><h3 id="welche-berechtigungen-braucht-nicasa" tabindex="-1">Welche Berechtigungen braucht Nicasa? <a class="header-anchor" href="#welche-berechtigungen-braucht-nicasa" aria-label="Permalink to &quot;Welche Berechtigungen braucht Nicasa?&quot;">​</a></h3><p>Nicasa benötigt Zugriff auf dein Dateisystem, um Bilder zu lesen und Einstellungen zu speichern. Für den Betrieb ist kein Internetzugang erforderlich.</p><h2 id="noch-fragen" tabindex="-1">Noch Fragen? <a class="header-anchor" href="#noch-fragen" aria-label="Permalink to &quot;Noch Fragen?&quot;">​</a></h2><p>Wenn du hier keine Antwort findest:</p><ol><li>Lies unsere <a href="/de/">vollständige Dokumentation</a></li><li>Durchsuche unsere <a href="https://github.com/nicasa-project/nicasa-support/issues" target="_blank" rel="noreferrer">GitHub-Issues</a></li><li>Erstelle bei Bedarf ein neues Issue</li></ol><p>Wir helfen gerne!</p>',57)])])}const b=i(t,[["render",s]]);export{g as __pageData,b as default};
